function lessonInputControls(){
  const controllable=nodes.filter(n=>catalog.find(c=>c.type===n.type).input||['ldr','switch','ultrasonic','dht11','dht22','bme280','bmp280','mpu6050','bh1750'].includes(n.type));
  if(!controllable.length)return '';
  return '<div class="lessoncontrols">'+controllable.map(n=>{
    const c=catalog.find(c=>c.type===n.type);
    const max=digitalSensors.has(n.type)||n.type==='switch'?1:n.type==='ultrasonic'?200:100;
    return `<label>${c.name} (${c.unit})<b id="lessonvalue_${n.id}">${n.value}</b><input aria-label="קלט ${c.name}" type="range" min="0" max="${max}" value="${n.value}" data-lesson-input="${n.id}"></label>`;
  }).join('')+'</div>';
}

